// 4x4 Bayer matrix threshold in [0..1).
// Screen-door transparency: avoids blending + sorting issues and keeps depth correct.
float bayer4x4(vec2 p) {
  // p is pixel coords; convert to 0..3
  int x = int(mod(p.x, 4.0));
  int y = int(mod(p.y, 4.0));
  int i = x + y * 4;
  // Values 0..15
  int v = 0;
  if (i == 0) v = 0;
  else if (i == 1) v = 8;
  else if (i == 2) v = 2;
  else if (i == 3) v = 10;
  else if (i == 4) v = 12;
  else if (i == 5) v = 4;
  else if (i == 6) v = 14;
  else if (i == 7) v = 6;
  else if (i == 8) v = 3;
  else if (i == 9) v = 11;
  else if (i == 10) v = 1;
  else if (i == 11) v = 9;
  else if (i == 12) v = 15;
  else if (i == 13) v = 7;
  else if (i == 14) v = 13;
  else v = 5;
